import json
import os
import urllib.request

# 交接契約：下游只認得下列四個欄位，其餘一律視為未驗證資料
CHANGE_SCHEMA = {
  "type": "object",
  "properties": {
    "booking_id": {"type": "string", "description": "訂位代號"},
    "change_type": {
      "type": "string",
      "enum": ["reschedule", "cancel", "seat_upgrade"],
    },
    "new_date": {"type": ["string", "null"], "format": "date"},
    "reason": {"type": "string", "description": "旅客提出的原因"},
  },
  "required": ["booking_id", "change_type", "new_date", "reason"],
  "additionalProperties": False,
}

API_KEY = os.environ["OPENAI_API_KEY"]
ENDPOINT = "https://api.openai.com/v1/chat/completions"


def call_model(prompt: str, schema: dict, model: str) -> str:
  """呼叫上游或下游模型，要求輸出符合 schema 的 JSON 字串。"""
  body = {
    "model": model,
    "messages": [
      {"role": "system", "content": "只輸出符合 schema 的 JSON，不要多寫其他文字。"},
      {"role": "user", "content": prompt},
    ],
    "response_format": {
      "type": "json_schema",
      "json_schema": {"name": "change_request", "schema": schema, "strict": True},
    },
  }
  request = urllib.request.Request(
    ENDPOINT,
    data=json.dumps(body).encode("utf-8"),
    headers={
      "Authorization": f"Bearer {API_KEY}",
      "Content-Type": "application/json",
    },
    method="POST",
  )
  with urllib.request.urlopen(request, timeout=30) as response:
    payload = json.load(response)
  return payload["choices"][0]["message"]["content"]
